const sessionId=typeof $json.sessionId==='string'?$json.sessionId.trim():'';
const requestId=typeof $json.requestId==='string'?$json.requestId.trim():'';
const rawPrompt=typeof $json.prompt==='string'?$json.prompt.trim():'';
const jobId=typeof $json.jobId==='string'?$json.jobId.trim():'';
const rawRatio=typeof $json.aspectRatio==='string'&&$json.aspectRatio.trim()?$json.aspectRatio.trim():'16:9';
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const ratios=['1:1','16:9','9:16','4:3','3:4','3:2','2:3'];
let error=null;
if(!uuid.test(sessionId)||!uuid.test(requestId)){error={code:'INVALID_SESSION',message:'The image request needs a valid conversation and request ID.'};}
else if(rawPrompt.length<3){error={code:'PROMPT_REQUIRED',message:'Describe the picture you want in a sentence or two.'};}
else if(rawPrompt.length>2000){error={code:'PROMPT_TOO_LONG',message:'Keep the picture description under 2000 characters.'};}
else if(!ratios.includes(rawRatio)){error={code:'INVALID_ASPECT_RATIO',message:'Use one of 1:1, 16:9, 9:16, 4:3, 3:4, 3:2 or 2:3.'};}
// Researched pages and article text are untrusted data. A prompt is a description
// of a picture, never an instruction to the agent or the provider.
const prompt=rawPrompt.replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim();
const proposedInput={sessionId,requestId,prompt,aspectRatio:rawRatio,jobId};
return {json:{valid:error===null,...proposedInput,proposedInput,...(error?{response:{ok:false,error}}:{})}};

const b=$json;
// Walk the response for the first image block. The bytes come back inline as
// base64, so nothing is downloaded from a provider URL.
let data='',mime='image/png';
const steps=Array.isArray(b.steps)?b.steps:[];
for(const step of steps){
  const content=Array.isArray(step&&step.content)?step.content:[];
  for(const block of content){
    if(block&&block.type==='image'&&typeof block.data==='string'&&block.data){
      data=block.data;
      if(typeof block.mime_type==='string'&&block.mime_type)mime=block.mime_type;
      break;
    }
  }
  if(data)break;
}
if(!data&&b.output_image&&typeof b.output_image.data==='string'){
  data=b.output_image.data;
  if(typeof b.output_image.mime_type==='string'&&b.output_image.mime_type)mime=b.output_image.mime_type;
}
const blocked=typeof b.error==='object'&&b.error&&/safety|blocked|policy/i.test(JSON.stringify(b.error));
const ready=Boolean(data);
let response=null;
if(!ready){
  response=blocked
    ?{ok:false,error:{code:'IMAGE_REJECTED',message:'The picture service refused that description. Try describing it differently.'}}
    :{ok:false,error:{code:'IMAGE_FAILED',message:'The picture could not be made. Nothing was saved.'}};
}
return {json:{ready,imageBase64:data,contentType:mime,...(response?{response}:{})}};

const input=$('Validate Image Request').first().json;
const saved=$json.image;
const ok=Boolean(saved&&saved.downloadUrl);
const response=ok
  ?{ok:true,savedImage:true,prompt:input.prompt,aspectRatio:input.aspectRatio,
     downloadUrl:saved.downloadUrl,imageId:saved.imageId,
     message:'The picture is saved and shown in the chat. Nothing was published anywhere.'}
  :{ok:false,savedImage:false,error:{code:'IMAGE_NOT_SAVED',message:'The picture was made but could not be saved locally.'}};
return {json:{response}};
